target.css:
:root {
  --ink: #153b45;
  --deep: #0b2c35;
  --paper: #fffdf7;
  --mist: #e8f0ed;
  --line: #bed1cb;
  --teal: #167b78;
  --seafoam: #cceae0;
  --amber: #e7a73c;
  --coral: #d95e4e;
  --white: #ffffff;
}

.relay,
.relay * {
  box-sizing: border-box;
}

.relay {
  width: 500px;
  padding: 14px 16px 12px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 18px;
}

.relay-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.station-mark {
  display: flex;
  align-items: center;
  gap: 9px;
}

.mast {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: var(--paper);
  background: var(--teal);
  border-radius: 10px 10px 4px 10px;
  font-size: 18px;
}

.eyebrow,
.panel-kicker,
.reading-label {
  margin: 0;
  color: var(--teal);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.1;
}

.relay h1 {
  margin: 2px 0 0;
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1;
}

.header-status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  color: var(--teal);
  background: var(--seafoam);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
}

.live-dot,
.legend {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.live-dot,
.teal {
  background: var(--teal);
}

.signal-nav {
  display: flex;
  gap: 6px;
  margin-top: 12px;
}

.channel {
  flex: 1;
  padding: 7px 8px;
  color: var(--ink);
  background: var(--mist);
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  text-align: left;
}

.channel span {
  margin-right: 5px;
  color: var(--teal);
  font-weight: 900;
}

.channel.active {
  color: var(--paper);
  background: var(--deep);
  border-color: var(--deep);
}

.channel.active span {
  color: var(--amber);
}

.signal-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.9fr 1fr;
  gap: 8px;
  margin-top: 9px;
}

.panel {
  min-height: 124px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.broadcast-panel {
  display: flex;
  flex-direction: column;
  color: var(--paper);
  background: var(--deep);
  border-color: var(--deep);
}

.beacon-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--seafoam);
}

.tide-panel {
  background: var(--mist);
}

.panel-heading,
.panel-footer,
.tide-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.broadcast-panel .panel-kicker {
  color: var(--seafoam);
}

.pulse,
.good-state,
.tide-time {
  padding: 3px 5px;
  border-radius: 4px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.05em;
}

.pulse {
  color: var(--deep);
  background: var(--amber);
}

.good-state {
  color: var(--paper);
  background: var(--teal);
}

.tide-time {
  color: var(--coral);
  background: var(--paper);
}

.broadcast-code {
  margin: 14px 0 2px;
  color: var(--amber);
  font-size: 19px;
  font-weight: 900;
  letter-spacing: 0.04em;
  line-height: 1;
}

.broadcast-copy {
  margin: 0;
  color: var(--paper);
  font-size: 11px;
  line-height: 1.35;
}

.panel-footer {
  margin-top: auto;
  padding-top: 7px;
  border-top: 1px solid var(--line);
  color: var(--teal);
  font-size: 9px;
  font-weight: 700;
}

.broadcast-panel .panel-footer {
  border-color: var(--teal);
  color: var(--seafoam);
}

.beacon-icon {
  margin: 8px 0 0;
  color: var(--teal);
  font-size: 25px;
  line-height: 1;
}

.beacon-reading {
  margin: 3px 0 1px;
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -0.06em;
  line-height: 1;
}

.beacon-reading span {
  margin-left: 2px;
  font-size: 10px;
  letter-spacing: 0;
}

.tide-list {
  display: grid;
  gap: 5px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}

.tide-list li {
  padding-bottom: 5px;
  border-bottom: 1px solid var(--line);
  font-size: 11px;
  line-height: 1;
}

.tide-list li:last-child {
  border-bottom: 0;
}

.tide-list strong,
.tide-list em {
  font-size: 9px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.04em;
}

.tide-list strong {
  color: var(--teal);
}

.tide-list em {
  color: var(--coral);
}

.relay-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
}

.relay-footer p {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0;
  color: var(--ink);
  font-size: 10px;
  font-weight: 700;
}

.amber {
  background: var(--amber);
}

.log-button {
  padding: 6px 9px;
  color: var(--paper);
  background: var(--teal);
  border: 0;
  border-radius: 7px;
  font-size: 10px;
  font-weight: 800;
}

.log-button span {
  margin-left: 5px;
  color: var(--amber);
  font-size: 13px;
}

